//! The vendor library (data/{tools,holders,collets}/<vendor>.toml, generated by
//! tools/tooling/gen.py from the makers' own public pages): every record real and cited, the
//! published numbers where the cites say, holder profiles from the nose, each tool assembles in
//! a holder, and the cite rules.
use forge_tooling::{CiteStatus, LibError, Library};

#[test]
fn vendor_records_are_real_and_cited() {
    let l = Library::builtin();
    let vendors = |v: &str| l.tools.iter().filter(|t| t.vendor == v).count();
    for (v, at_least) in [
        ("Harvey Tool", 30),
        ("Helical Solutions", 30),
        ("Lakeshore Carbide", 30),
        ("OSG", 20),
        ("Guhring", 20),
        ("Tormach", 10),
    ] {
        assert!(vendors(v) >= at_least, "{v}: {}", vendors(v));
    }
    for t in l.tools.iter().filter(|t| !t.vendor.is_empty()) {
        assert!(t.real, "{}", t.id);
        for p in ["dc", "lcf", "dcon", "oal"] {
            assert!(t.cites.iter().any(|c| c.path == p), "{}: {p}", t.id);
        }
        // every tool builds its exact body in a holder
        t.shape(t.lcf + 2.0, Some(l.holder("bt40-er32").unwrap()))
            .unwrap_or_else(|e| panic!("{}: {e:?}", t.id));
    }
    let real_holders: Vec<_> = l.holders.iter().filter(|h| h.real).collect();
    assert!(real_holders.len() >= 150, "{}", real_holders.len());
    for h in &real_holders {
        assert_eq!(h.profile[0][0], 0.0, "{}", h.id);
        assert!(h.profile.last().unwrap()[0] <= h.gauge_length + 1e-9, "{}", h.id);
        assert!(h.cites.iter().any(|c| c.path == "profile"), "{}", h.id);
    }
    assert!(l.collets.iter().filter(|c| c.real).count() >= 25);
    assert!(l.collet_nuts.len() >= 5 && l.pull_studs.len() >= 5);
}

#[test]
fn published_numbers_land_where_the_cites_say() {
    let l = Library::builtin();
    // Harvey 792208: 1/8 in, 3/8 LOC, 1-1/2 OAL, 2 flutes
    let t = l.tool("harvey-792208").unwrap();
    assert_eq!(
        (t.dc, t.lcf, t.dcon, t.oal, t.nof),
        (3.175, 9.525, 3.175, 38.1, 2)
    );
    // Schunk 1388977 (CAT40 ER16, L1 = 63.5): the nut and body are 28 mm to the front flange face
    // (L1 - L5 = 19.05), then the CAT40 flange (Maritool drawing) to the gauge line
    let h = l.holder("schunk-1388977").unwrap();
    assert_eq!(h.gauge_length, 63.5);
    assert_eq!(h.profile[0], [0.0, 28.0]);
    assert!(
        h.profile
            .iter()
            .any(|r| (r[0] - 44.45).abs() < 1e-9 && r[1] == 63.5),
        "{:?}",
        h.profile
    );
    // a holder with only its nose published: the flange diameter stands in behind the nose, and
    // the cite says it is not published
    let n = l.holder("techniks-22225").unwrap();
    assert_eq!(n.profile, vec![[0.0, 27.432], [0.0, 63.5], [70.104, 63.5]]);
    let c = n.cites.iter().find(|c| c.path == "profile").unwrap();
    assert!(
        c.status == CiteStatus::Estimate && c.basis.contains("errs large"),
        "{c:?}"
    );
}

#[test]
fn cite_rules() {
    let base = "[[tool]]\nid = \"x\"\ntype = \"flat\"\ndc = 6\nlcf = 12\ndcon = 6\noal = 50\n";
    let mut l = Library::default();
    // not real: no cites needed
    l.add("a.toml", base).unwrap();
    // real without cites: refused, naming what is uncited
    let e = Library::default()
        .add("b.toml", &base.replace("oal = 50", "oal = 50\nreal = true"))
        .unwrap_err();
    assert!(
        matches!(&e, LibError::Bad { field: "real", why, .. } if why.contains("dc") && why.contains("oal")),
        "{e:?}"
    );
    // a user's own values: status "user", no source needed
    let mut user = base
        .replace("id = \"x\"", "id = \"mine\"")
        .replace("oal = 50", "oal = 50\nreal = true");
    for p in ["dc", "lcf", "dcon", "oal"] {
        user.push_str(&format!("[[tool.cite]]\npath = \"{p}\"\nstatus = \"user\"\n"));
    }
    Library::default().add("c.toml", &user).unwrap();
    // a published cite needs its source and date; an estimate its basis; a cite names a field
    let bad = |extra: &str| {
        Library::default()
            .add("d.toml", &format!("{base}[[tool.cite]]\n{extra}"))
            .unwrap_err()
    };
    assert!(matches!(
        bad("path = \"dc\"\nstatus = \"published\"\n"),
        LibError::Missing { field: "source", .. }
    ));
    assert!(matches!(
        bad("path = \"dc\"\nstatus = \"published\"\nsource = \"s\"\n"),
        LibError::Missing { field: "taken", .. }
    ));
    assert!(matches!(
        bad("path = \"dc\"\nstatus = \"estimate\"\n"),
        LibError::Missing { field: "basis", .. }
    ));
    assert!(matches!(
        bad("path = \"colour\"\nstatus = \"user\"\n"),
        LibError::Bad { field: "path", .. }
    ));
}

#[test]
fn turning_records_parse() {
    let src = r#"
[[insert]]
id = "x-CNMG120408"
code = "CNMG 120408"
ic = 12.7
s = 4.76
re = 0.8
[[turn_holder]]
id = "x-PCLNR2525M12"
code = "PCLNR2525M12"
kind = "holder"
h = 25
b = 25
l1 = 150
f = 32
kr = 95
hand = "R"
[[turn_holder]]
id = "x-bar"
code = "S20S-MCLNR12"
kind = "bar"
dmm = 20
l1 = 250
f = 13
kr = 95
hand = "R"
min_bore = 25
"#;
    let (ins, hs) = forge_tooling::turning::parse(src).unwrap();
    assert_eq!(ins[0].code, "CNMG120408");
    assert_eq!(hs.len(), 2);
    assert_eq!(hs[1].min_bore, Some(25.0));
    assert!(
        forge_tooling::turning::parse(
            &src.replace("hand = \"R\"\n[[turn_holder]]", "hand = \"Q\"\n[[turn_holder]]")
        )
        .is_err()
    );
}

#[test]
fn builtin_files_are_named_by_vendor() {
    let files = forge_tooling::builtin_files();
    assert_eq!(files[0].0, "builtin/fixtures.toml");
    for f in [
        "builtin/tools/harvey.toml",
        "builtin/holders/schunk.toml",
        "builtin/collets/rego-fix.toml",
        "builtin/turning/sumitomo.toml",
    ] {
        assert!(files.iter().any(|(n, _)| *n == f), "{f}");
    }
    // the files read back to the same library
    let mut l = Library::default();
    for (n, s) in files {
        l.add(n, s).unwrap();
    }
    assert_eq!(l, Library::builtin());
}

/// The cutting data cites every value (published, estimate with its basis, or unknown); the
/// P group carries Klippel et al.'s measured Ck45 Kienzle ranges (CC BY 4.0) and its point
/// values lie inside them.
#[test]
fn cutting_data_is_cited_per_value() {
    let lib = Library::builtin();
    assert_eq!(lib.cutting.len(), 7);
    for g in &lib.cutting {
        assert!(g.real, "group {}", g.group);
        // a value the record holds is cited; plastics (O) hold no Kienzle data and no HSS speed
        let held = |f: &str| match f {
            "vc_hss" => g.vc_hss.is_finite(),
            "kc1_1" => g.kc1_1.is_finite(),
            "mc" => g.mc.is_finite(),
            _ => true,
        };
        if g.group == "O" {
            assert!(!g.kc1_1.is_finite() && !g.mc.is_finite());
        }
        for f in ["vc_carbide", "vc_hss", "fz_d1", "fz_d20", "kc1_1", "mc"]
            .into_iter()
            .filter(|f| held(f))
        {
            let c = g
                .cites
                .iter()
                .find(|c| c.path == f)
                .unwrap_or_else(|| panic!("{} {f}", g.group));
            assert!(
                c.status == CiteStatus::Published || !c.basis.is_empty(),
                "{} {f}",
                g.group
            );
        }
    }
    let p = lib.group("P").unwrap();
    assert_eq!(
        (p.kc1_1_range, p.mc_range),
        (Some([1368.0, 1935.0]), Some([0.17, 0.51]))
    );
    let r = p.kc1_1_range.unwrap();
    assert!(p.kc1_1 >= r[0] && p.kc1_1 <= r[1]);
    let c = p.cites.iter().find(|c| c.path == "kc1_1_range").unwrap();
    assert_eq!(c.status, CiteStatus::Published);
    assert!(c.source.contains("2209.04197") && c.note.contains("CC BY 4.0"));
    assert_eq!(p.upper(), (1935.0, 0.51));
}

/// Kienzle rows (as forge-material's Ti-6Al-4V record holds Klippel et al.'s Table 16) are read
/// between rows at the cut's speed and held at the end rows outside them.
#[test]
fn stock_kienzle_rows() {
    let ti = forge_tooling::feeds::Stock::new(
        "Ti-6Al-4V annealed",
        "S",
        Some((
            vec![40.0, 50.0, 500.0],
            vec![1253.0, 1061.0, 662.0],
            vec![0.22, 0.28, 0.41],
        )),
        "test rows",
    );
    let (kc, mc, kr, mr, _) = ti.kienzle_at(45.0).unwrap();
    assert!(
        (kc - 1157.0).abs() < 1e-9 && (mc - 0.25).abs() < 1e-12,
        "{kc} {mc}"
    );
    assert_eq!((kr, mr), ([662.0, 1253.0], [0.22, 0.41]));
    let (kc, _, _, _, how) = ti.kienzle_at(600.0).unwrap();
    assert!(kc == 662.0 && how.contains("over the data"));
    // rows that do not line up are dropped, not guessed
    assert!(
        forge_tooling::feeds::Stock::new("x", "P", Some((vec![1.0], vec![], vec![])), "")
            .kienzle_at(10.0)
            .is_none()
    );
    assert_eq!(forge_tooling::feeds::iso_group_of_family("aluminium"), Some("N"));
    assert_eq!(forge_tooling::feeds::iso_group_of_family("plastic"), Some("O"));
    assert_eq!(forge_tooling::feeds::iso_group_of_family("rubber"), None);
    use forge_tooling::feeds::Substrate;
    assert_eq!(Substrate::of("Solid Carbide"), Substrate::Carbide);
    assert_eq!(Substrate::of("Micrograin Carbide"), Substrate::Carbide);
    assert_eq!(Substrate::of("HSS-Co"), Substrate::Hss);
    assert_eq!(Substrate::of("PCD"), Substrate::Other);
    assert_eq!(Substrate::of(""), Substrate::Unknown);
}

/// FEEDS-SPEEDS' preset spec: per (ISO group, class) a representative named "<group> <class>",
/// and every maker row as "<group> <class> <maker's material>"; each cited once; the numbers
/// are the maker's printed inch values converted exactly.
#[test]
fn presets_follow_the_spec() {
    let l = Library::builtin();
    let mut n = 0;
    for t in l.tools.iter().filter(|t| t.real) {
        let mut names = std::collections::BTreeSet::new();
        for p in &t.presets {
            n += 1;
            let mut it = p.name.splitn(3, ' ');
            let (g, class) = (it.next().unwrap(), it.next().unwrap_or(""));
            assert_eq!(g, p.group, "{}", t.id);
            assert!("PMKNSHO".contains(g) && g.len() == 1, "{}: {g}", t.id);
            assert!(
                ["slot", "rough", "finish", "general"].contains(&class),
                "{}: {class}",
                t.id
            );
            assert!(names.insert(p.name.clone()), "{}: {} twice", t.id, p.name);
            assert!(p.vc > 0.0 && p.fz > 0.0, "{}: {}", t.id, p.name);
            let c = t
                .cites
                .iter()
                .find(|c| c.path == format!("preset.{}", p.name))
                .unwrap_or_else(|| panic!("{}: {} uncited", t.id, p.name));
            assert!(!c.value.is_empty() && !c.source.is_empty(), "{}", t.id);
            // a material-named row restates its material; the representative names one too
            if let Some(mat) = it.next() {
                assert!(c.value.starts_with(mat), "{}: {}", t.id, c.value);
            }
        }
        // every (group, class) that has rows has its representative
        for p in &t.presets {
            let rep: String = p.name.splitn(3, ' ').take(2).collect::<Vec<_>>().join(" ");
            assert!(names.contains(&rep), "{}: no {rep}", t.id);
        }
    }
    assert!(n >= 2000, "{n}");
    // Harvey 792208 (1/8", uncoated): N's representative is wrought aluminium (FEEDS-SPEEDS'
    // list), 1000 SFM and .00183 IPT slotting at 1x D radial, .5x D axial
    let t = l.tool("harvey-792208").unwrap();
    let p = t.presets.iter().find(|p| p.name == "N slot").unwrap();
    // exact to the 6 dp the file is written in
    assert!((p.vc - 304.8).abs() < 1e-9 && (p.fz - 0.00183 * 25.4).abs() < 1e-9);
    assert_eq!((p.ap, p.ae), (Some(0.5 * 3.175), Some(3.175)));
    let c = t.cites.iter().find(|c| c.path == "preset.N slot").unwrap();
    assert_eq!(c.status, CiteStatus::Estimate);
    assert!(c.value.starts_with("ALUMINUM ALLOYS: Wrought"), "{}", c.value);
    assert!(
        c.value.contains("1000 SFM") && c.value.contains(".00183 IPT"),
        "{}",
        c.value
    );
    // every Harvey row is kept too: the High Coppers slotting row at 225 SFM
    let cu = t
        .presets
        .iter()
        .find(|p| p.name == "N slot COPPER ALLOYS: High Coppers - 90%+ (C1xxxx)")
        .unwrap();
    assert!((cu.vc - 225.0 * 0.3048).abs() < 1e-9);
    // Helical's finishing column is a programmed feed at its stated RDOC
    let h = l.tools.iter().filter(|t| t.vendor == "Helical Solutions");
    let fin: Vec<_> = h
        .flat_map(|t| {
            t.cites
                .iter()
                .filter(|c| c.path.split(' ').nth(1) == Some("finish"))
        })
        .collect();
    assert!(!fin.is_empty() && fin.iter().all(|c| c.note.contains("programmed at ae")));
    // "Up to" depths are the source's upper limit, and the cite says so
    assert!(
        l.tools
            .iter()
            .flat_map(|t| &t.cites)
            .any(|c| c.note.contains("upper limit"))
    );
}

/// A part's stock material picks the maker's own row on the tool (Tool::preset_for_material):
/// an exact alloy name over a family pattern, the slowest of the maker's hardness classes; a
/// narrow contour is a finishing cut (Tool::class_for).
#[test]
fn presets_by_stock_material_and_class() {
    let l = Library::builtin();
    let text = |t: &forge_tooling::Tool, g: &str, c: &str, m: &str| {
        t.preset_for_material(g, c, m).map(|(p, _)| p.name.clone())
    };
    let harvey = l.tool("harvey-792208").unwrap();
    // brass C36000 by Harvey's "C3xxxx" family, not the wrought-aluminium representative
    let n = text(harvey, "N", "slot", "C36000 H02").unwrap();
    assert!(n.contains("Brass"), "{n}");
    let n = text(harvey, "N", "slot", "6061-T6").unwrap();
    assert!(n.contains("Wrought"), "{n}");
    // a material the maker's texts do not name: none (the caller takes the representative)
    assert_eq!(text(harvey, "N", "slot", "Gray iron class 30"), None);
    let helical = l.tool("helical-30017").unwrap();
    for (g, m, want) in [
        ("S", "Inconel 718 aged", "NICKEL ALLOY"),
        ("S", "Ti-6Al-4V annealed", "TITANIUM ALLOY"),
        ("M", "304 annealed", "AUSTENITIC"),
        ("M", "17-4PH H1150", "PH STAINLESS"),
        ("P", "4140 annealed", "LOW ALLOY"),
    ] {
        let n = text(helical, g, "slot", m).unwrap_or_else(|| panic!("{m}"));
        assert!(n.contains(want), "{m}: {n}");
    }
    // the slowest of the maker's hardness classes for the same alloys
    let (p, _) = helical.preset_for_material("M", "slot", "304 annealed").unwrap();
    let slowest = helical
        .presets
        .iter()
        .filter(|q| q.name.starts_with("M slot AUSTENITIC"))
        .map(|q| q.vc)
        .fold(f64::INFINITY, f64::min);
    assert_eq!(p.vc, slowest);
    // a contour at 10% D or under finishes, wider roughs; clearing stays rough at any width
    assert_eq!(harvey.class_for("contour", 0.3175, "N"), "finish");
    assert_eq!(harvey.class_for("contour", 1.0, "N"), "rough");
    assert_eq!(harvey.class_for("clear", 0.3, "N"), "rough");
    assert_eq!(harvey.class_for("slot", 3.175, "N"), "slot");
}

/// Parting: a groove insert, the blade it seats in and the block the blade clamps in, each
/// read with its cites (CAM-TURN's shape: the cut is the insert's width, the reach the blade's
/// cdx, the blade body its t_blade).
#[test]
fn parting_records_read() {
    let src = r#"
[[groove_insert]]
id = "x-gi"
code = "GI 3.00-0.20"
width = 3.0
re = 0.2
real = true
[[groove_insert.preset]]
name = "P"
group = "P"
vc = 100
fz = 0.08
[[groove_insert.cite]]
path = "code"
status = "published"
source = "s"
taken = "2026-11-24"
[[groove_insert.cite]]
path = "width"
status = "published"
source = "s"
taken = "2026-11-24"
[[groove_insert.cite]]
path = "re"
status = "published"
source = "s"
taken = "2026-11-24"

[[blade]]
id = "x-bl"
code = "BL 26-3"
h = 26
t_blade = 2.4
l1 = 110
cdx = 40
max_bar = 80
hand = "N"

[[tool_block]]
id = "x-tb"
code = "TB 25"
h = 25
b = 25
l1 = 110
"#;
    // a real record must cite its preset
    let mut l = Library::default();
    assert!(matches!(
        l.add("x.toml", src),
        Err(LibError::Bad { field: "real", .. })
    ));
    let ok = src.replace(
        "[[groove_insert.cite]]\npath = \"code\"",
        "[[groove_insert.cite]]\npath = \"preset.P\"\nstatus = \"published\"\nsource = \"s\"\ntaken = \"2026-11-24\"\n[[groove_insert.cite]]\npath = \"code\"",
    );
    let mut l = Library::default();
    l.add("x.toml", &ok).unwrap();
    assert_eq!((l.groove_inserts[0].width, l.groove_inserts[0].re), (3.0, 0.2));
    assert_eq!(l.groove_inserts[0].presets[0].fz, 0.08);
    let b = &l.blades[0];
    assert_eq!((b.h, b.t_blade, b.cdx, b.max_bar), (26.0, 2.4, 40.0, Some(80.0)));
    assert_eq!(l.tool_blocks[0].h, 25.0);
    // a blade with no reach is refused by name
    let mut l = Library::default();
    let e = l.add("x.toml", &ok.replace("cdx = 40\n", "")).unwrap_err();
    assert!(matches!(e, LibError::Missing { field: "cdx", .. }), "{e:?}");
}

/// Turning presets from the makers' grade tables (FEEDS-SPEEDS): Sumitomo's "Recommended
/// Cutting Conditions" (A13) for GU in AC8115P, mild steel: vc 260-350-500 m/min, f 0.1-0.25-0.4,
/// ap 1.0-2.5-4.0, the printed optimum kept.
#[test]
fn insert_presets_from_grade_tables() {
    let l = Library::builtin();
    let i = l
        .inserts
        .iter()
        .find(|i| i.id == "sumitomo-CNMG120408N-GU")
        .unwrap();
    let p = i.presets.iter().find(|p| p.name == "P GU AC8115P").unwrap();
    assert_eq!((p.vc, p.fz, p.ap), (350.0, 0.25, Some(2.5)));
    let c = i.cites.iter().find(|c| c.path == "preset.P GU AC8115P").unwrap();
    assert_eq!(c.status, CiteStatus::Published);
    assert!(c.value.contains("260-350-500"), "{}", c.value);
    // every insert preset is cited and positive; the makers that print vc per grade only are
    // estimates (matched by the grades the insert is offered in)
    let mut n = 0;
    for i in &l.inserts {
        for p in &i.presets {
            n += 1;
            assert!(p.vc > 0.0 && p.fz > 0.0, "{}: {}", i.id, p.name);
            let c = i
                .cites
                .iter()
                .find(|c| c.path == format!("preset.{}", p.name))
                .unwrap();
            if i.maker == "Ingersoll" || i.maker == "Korloy" {
                assert_eq!(c.status, CiteStatus::Estimate, "{}: {}", i.id, p.name);
            }
        }
    }
    assert!(n >= 500, "{n}");
}

/// The real tools found for the shop parts (raw/real-tools): CAM-TURN's parting blade and 26 mm
/// U-drill, CAM-CORE's 18.5 / 6 / 5.5 mm drills and 1.5-pitch thread mill.
#[test]
fn shop_part_tools() {
    let l = Library::builtin();
    let b = l.blades.iter().find(|b| b.id == "tungaloy-CGP32-3D").unwrap();
    assert_eq!((b.h, b.t_blade, b.l1, b.max_bar), (32.0, 2.4, 150.0, Some(100.0)));
    let gi = l
        .groove_inserts
        .iter()
        .find(|g| g.id == "tungaloy-SGM3-020")
        .unwrap();
    assert_eq!((gi.width, gi.re, gi.head), (3.0, 0.2, Some(20.0)));
    let u = l.tool("sumitomo-WDX260D4S32").unwrap();
    assert_eq!((u.dc, u.dcon, u.angle), (26.0, 32.0, 180.0));
    u.shape(u.lcf + 2.0, None).unwrap();
    for (id, d) in [
        ("guhring-9055180185000", 18.5),
        ("guhring-9055180060000", 6.0),
        ("guhring-9055180055000", 5.5),
    ] {
        let t = l.tool(id).unwrap();
        assert_eq!((t.dc, t.angle), (d, 130.0), "{id}");
        assert!(t.real && !t.presets.is_empty(), "{id}");
    }
    let tm = l.tool("tungaloy-MTEC0807C171.5ISO").unwrap();
    assert_eq!((tm.dc, tm.tp, tm.nof), (7.0, 1.5, 3));
}

/// An insert's preset for a cut: the grade asked (an unknown one lists the grades); within the
/// grade the row naming the stock material, else the 10th percentile by speed of the grade's
/// rows; no grade asked, the 10th percentile of all the insert's rows for the group. The
/// turning resolver's library layer carries it with its cite.
#[test]
fn insert_preset_for_grade_and_material() {
    let l = Library::builtin();
    let ins = l
        .inserts
        .iter()
        .find(|i| i.id == "sumitomo-CNMG120408N-GU")
        .unwrap();
    // CAM-HAAS's example: P GU AC8115P = vc 350, f 0.25, ap 2.5 (the printed optimum)
    let p = ins.preset_for("P", Some("AC8115P"), None).unwrap().unwrap();
    assert_eq!((p.preset.vc, p.preset.fz, p.preset.ap), (350.0, 0.25, Some(2.5)));
    assert!(p.why.contains("10th percentile"), "{}", p.why);
    // a grade the maker prints none for: the grades it has, to choose from
    let e = ins.preset_for("P", Some("XX99"), None).unwrap_err();
    assert!(e.contains(&"AC8115P".to_string()), "{e:?}");
    // no grade: the 10th percentile by speed over every grade's material rows for P
    let d = ins.preset_for("P", None, None).unwrap().unwrap();
    let rows: Vec<f64> = ins
        .presets
        .iter()
        .filter(|q| q.group == "P" && q.name.split(' ').count() > 3)
        .map(|q| q.vc)
        .collect();
    let q = forge_tooling::feeds::Quantiles::of(rows).unwrap();
    assert_eq!(d.preset.vc, q.p10);
    assert!(d.why.contains("grade not stated"), "{}", d.why);
    // a named material picks its row in the grade: Sumitomo's medium/high carbon steel row
    let m = ins
        .preset_for("P", Some("AC8025P"), Some("C45 bright"))
        .unwrap()
        .unwrap();
    assert!(
        m.why.contains("10th percentile") || m.why.contains("stock material"),
        "{}",
        m.why
    );
    // the turning resolver's library layer, with the cite's page
    let t = forge_tooling::resolve::TurnData::from_pick(&p, Some(95.0));
    assert_eq!((t.vc, t.f, t.ap), (Some(350.0), Some(0.25), Some(2.5)));
    assert!(t.source.contains("sumitool.com"), "{}", t.source);
    // no preset for the group: none (the op asks for vc and f)
    assert!(ins.preset_for("N", None, None).unwrap().is_none());
}

/// A turning tool with no preset for the group takes the generic turning class: P10 of the
/// makers' insert rows for the group, labelled `material` with the class's spread.
#[test]
fn generic_turning_default() {
    use forge_tooling::resolve::{self, Source, Spindle, TurnAsk, TurnData};
    let l = Library::builtin();
    let g = l.turn_generic("P", Some("wood")).unwrap();
    assert_eq!((g.group.as_str(), g.family.as_str()), ("P", "*"));
    assert!(g.makers.len() >= 2 && g.n >= 10);
    let t = TurnData::from_generic(g, Some(95.0));
    let r = resolve::turning(
        &TurnAsk::default(),
        &t,
        l.group("P"),
        &Spindle {
            rpm: [50.0, 4000.0],
            max_feed: 0.0,
            power: &[],
        },
        [20.0, 60.0],
    )
    .unwrap();
    assert_eq!((r.vc.v, r.vc.source), (g.vc.p10, Source::Material));
    assert_eq!((r.f.v, r.f.source), (g.f.p10, Source::Material));
    assert!(r.vc.note.contains("10th percentile"), "{}", r.vc.note);
    let sp = r.spread.unwrap();
    assert_eq!((sp.vc, sp.n), (g.vc, g.n));
    // no class for a group with no turning data: nothing to default to (the op is refused)
    assert!(l.turn_generic("N", None).is_none());
}
